+static inline bool is_vector_ctz_popcnt_evex(const Node* n) {
+  assert(n->bottom_type()->isa_vect(), "not a vector");
+  BasicType bt = Matcher::vector_element_basic_type(n);
+  int vlen_bytes = (int)Matcher::vector_length_in_bytes(n);
+  if (bt == T_BYTE || bt == T_SHORT || bt == T_INT || bt == T_LONG) {
+    return is_vector_popcount_predicate(bt) &&
+           (VM_Version::supports_avx512vl() || vlen_bytes == 64);
+  }
+  return false;
+}
